if(tg?.themeParams){const root=document.documentElement.style,theme=tg.themeParams;for(const [key,value] of Object.entries({"--bg":theme.bg_color,"--surface":theme.secondary_bg_color,"--text":theme.text_color,"--muted":theme.hint_color,"--primary":theme.button_color})){if(value)root.setProperty(key,value)}}
const state={route:"overview",data:null,lastSearch:[],selected:null,connection:null,pairing:null,devices:null,lastSyncAt:null,activeRequests:new Set(),searchVisible:10,pipelineDeadlineFilter:"all",reportText:"",latestAiReport:null};
const content=document.querySelector("#content"),title=document.querySelector("#page-title"),subtitle=document.querySelector("#page-subtitle"),loader=document.querySelector("#loader"),toast=document.querySelector("#toast");
